import logging

from taf.internal.robot_typecasts import to_boolean
from .deltaSCFCalculatorSelector import DeltaSCFCalculatorSelector
from .scf_operations import SCFOperations

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class scf(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self, **kwargs):
        super(scf, self).__init__(**kwargs)
        self.scf_operations = SCFOperations()

    def load_scf(self, file_path):
        """ Load .xml file known as Site Configuration File.
        Data will be stored in volatile memory, loaded file will not be edited
        until `save_scf` keyword call.

        :param file_path: path as string
        """
        return self.scf_operations.load_scf(file_path)

    def save_scf(self, file_path, xml_declaration=True, encoding='UTF-8',
                 standalone=True):
        """ Save all changes, if another path than one during load operation
        given then new file will be created, old one remains without changes.

        :param file_path: path as string
        :param xml_declaration: default: True
        :param encoding: default: 'UTF-8'
        :param standalone: default: True
        """
        xml_declaration = to_boolean(xml_declaration)
        standalone = to_boolean(standalone)
        return self.scf_operations.save_scf(file_path, xml_declaration,
                                            encoding, standalone)

    def get_value_from_scf(self, **kwargs):
        """ Reads single value of p element. Raises exception if more or less
        than one element found. If there is not direct way to point at specific
        element (some of them are not named properly or there are duplicated names),
        and one can avoid exception if multiple matches found, index attribute can be used to
        return specific element from list of matches. For values of managed object's attributes
        keyword 'get_mo_attribute' should be used.

        :param dist_name: in <managedObject> as 'distName', SBTS prefix can be
                          ommited e.g.: 'MRBTS-1/NRBTS-1/NRCELL-1' is valid. None is default value.
        :param p_name: 'name' attribute in <p> tag, None is default value
        :param list_name: 'name' attribute in <list> tag, None is default value
        :param index: optional parameter, should be castable to int (int or str).
                      Should be used if more than one match expected. Indexing starts from 0.
        :return: read value as string.
        :raises KeyError if no elements found
        :raises MultipleMatches if more than one element found and index is not given
        :raises IndexError if given index is bigger or equal to number of matches
        """
        return self.scf_operations.get_value_from_scf(**kwargs)

    def get_all_values_from_scf(self, **kwargs):
        """  Returns list of all matched values of p elements, does expect any specific
        number of matches. For values of managed object's attributes keyword 'get_mo_attribute'
        should be used.

        :param dist_name: in <managedObject> as 'distName', SBTS prefix can be
                          ommited e.g.: both 'SBTS-1900/NGNODEB-1' and 'NGNODE-1'
                          are valid and equivalent. None is default value.
        :param p_name: 'name' attribute in <p> tag, None is default value
        :param list_name: 'name' attribute in <list> tag, None is default value
        :return: read value as string.
        """
        return self.scf_operations.get_all_values_from_scf(**kwargs)

    def get_all_values_from_scf_by_pattern(self, **kwargs):
        """ Same as `get_all_values_from_scf` but expects regular expressions\
        in dist_name, p_name or list_name. """
        return self.scf_operations.get_all_values_from_scf_by_pattern(**kwargs)

    def get_all_dist_names_of_specific_class(self, mo_class):
        """  Returns list of all dist names that match specific class, does expect specific
        class name from managed object.

        :param mo_class: in <managedObject> as 'class', e.g.: 'com.nokia.sbts:RAP'
        :return: list of dist names values that match provided class
        """
        return self.scf_operations.get_all_dist_names_of_specific_class(mo_class)

    def get_all_dist_names_by_pattern(self, pattern):
        """  Returns list of all dist names that match regex pattern, does expect regex.

        :param pattern: regular expression, e.g.: 'RMOD*'
        :return: list of dist names values that match regex pattern
        """
        return self.scf_operations.get_all_dist_names_by_pattern(pattern)

    def modify_scf_element(self, value, **kwargs):
        """ Reads single value. Attributes are mapped to SCF element's attributes.
        Raises exception if more or less than one element found.
        If there is not direct way to point at specific element (some of them
        are not named properly or there are duplicated names), and one can avoid
        exception if multiple matches found, index attribute can be used to
        modify specific element from list of matches.

        :param value: new value
        :param dist_name: in <managedObject> as 'distName', SBTS prefix can be ommited
                          e.g.: both 'SBTS-1900/NGNODEB-1' and 'NGNODE-1' are valid
                          and equivalent. None is default value.
        :param p_name: 'name' attribute in <p> tag, None is default value
        :param list_name: 'name' attribute in <list> tag, None is default value
        :param index: optional parameter, should be castable to int (int or str).
                      Should be used if more than one match expected. Indexing starts from 0.
        :raises KeyError if no elements found
        :raises MultipleMatches if more than one element found and index is not given
        :raises IndexError if given index is bigger or equal to number of matches
        """
        return self.scf_operations.modify_scf_element(value, **kwargs)

    def remove_element_from_scf(self, **kwargs):
        """ Removes element from loaded SCF. Attributes are mapped to SCF element's
        attributes. If p_name or index given it removes only single element. If not
        the whole managedObject is removed. Changes are saved only after save_scf
        keyword.

        :param dist_name: in <managedObject> as 'distName', SBTS prefix can be ommited e.g.:
                          both 'SBTS-1900/NGNODEB-1' and 'NGNODE-1' are valid and equivalent.
                          None is default value.
        :param list_name: 'name' attribute in <list> tag, None is default value
        :param p_name: 'name' attribute in <p> tag, None is default value. If not
                       given and param index not given the whole managedObject is removed
        :param index: optional parameter, should be castable to int (int or str). Should be
                      used if more than one match expected. Indexing starts from 0. If not
                      given and param p_name not given the whole managedObject is removed.
        """
        return self.scf_operations.remove_block_from_scf(**kwargs)

    def remove_list_from_scf(self, dist_name, list_name):
        """ Removes list from loaded SCF inside managed object indicated in 'dist_name'.

        :param str dist_name: in <managedObject> as 'distName', SBTS prefix can be ommited e.g.:
                              both 'SBTS-1900/NGNODEB-1' and 'NGNODE-1' are valid and equivalent.
        :param str list_name: 'name' attribute in <list> tag
        :raise ElementNotFound: when 'dist_name' not found inside given SCF
        """
        self.scf_operations.remove_list_from_scf(dist_name=dist_name, list_name=list_name)

    def add_element_to_scf(self, dist_name, p_name, value):
        """ Adds element to object in loaded SCF. The object is mapped by the attribute
        distName. The element is added at the end of list of objects children.
        Changes are saved only after save_scf keyword.

        :param dist_name: in <managedObject> as 'distName', SBTS prefix can be ommited e.g.:
                          both 'SBTS-1900/NGNODEB-1' and 'NGNODE-1' are valid and equivalent.
        :param p_name: name of attribute of new element
        :param value: value of new element
        """
        self.scf_operations.add_element_to_scf(dist_name, p_name, value)

    def add_list_to_scf(self, dist_name, list_name):
        """ Adds an empty list to object in loaded SCF. The object is mapped by the attribute
        distName. Changes are saved only after save_scf keyword.

        :param dist_name: in <managedObject> as 'distName', SBTS prefix can be ommited e.g.:
                          both 'SBTS-1900/NGNODEB-1' and 'NGNODE-1' are valid and equivalent.
        :param list_name: name of the new list
        """
        self.scf_operations.add_list_to_scf(dist_name, list_name)

    def add_item_to_list(self, dist_name, list_name, elements):
        """ Adds the items from elements dictionary (name, value) to the list in object in loaded SCF.
        The object is mapped by the attribute distName. Changes are saved only after save_scf keyword.

        :param dist_name: in <managedObject> as 'distName', SBTS prefix can be ommited e.g.:
                          both 'SBTS-1900/NGNODEB-1' and 'NGNODE-1' are valid and equivalent.
        :param list_name: name of the target list
        :param elements: dictionary of elements added to the list, key is an element name, value is an element value.
        """
        self.scf_operations.add_item_to_list(dist_name, list_name, elements)

    def add_elements_to_list(self, dist_name, list_name, elements):
        """ Adds the elements from elements list to the list in object in loaded SCF.
        The object is mapped by the attribute distName. Changes are saved only after save_scf keyword.

        :param dist_name: in <managedObject> as 'distName', SBTS prefix can be ommited e.g.:
                          both 'SBTS-1900/NGNODEB-1' and 'NGNODE-1' are valid and equivalent.
        :param list_name: name of the target list
        :param elements: list of elements to add to the target list
        """
        self.scf_operations.add_elements_to_list(dist_name, list_name, elements)

    def add_object_to_scf(self, class_name, dist_name, version, operation='create'):
        """ Adds whole managedObject to loaded SCF. All parameters are mandatory and
        are addded as attributes to the object. Changes are saved only after save_scf keyword.

        :param class_name: added as attribute 'class'
        :param dist_name: in <managedObject> as 'distName', SBTS prefix can be ommited e.g.:
                          both 'SBTS-1900/NGNODEB-1' and 'NGNODE-1' are valid and equivalent.
        :param version: added as attribute 'version'
        :param operation: added as attribute 'operation', default value is 'create'
        """
        self.scf_operations.add_object_to_scf(class_name, dist_name, version, operation)

    def is_object_in_scf(self, dist_name):
        """ Checks whether given object exists in loaded SCF. The object is mapped by the attribute distName.

        :param str dist_name: distName of checked object
        :return: True if object exists, False otherwise.
        :rtype: bool
        """
        return self.scf_operations.is_in_scf(dist_name)

    def is_list_in_object(self, dist_name, list_name):
        """ Checks whether given list exists in given object. The object is mapped by the attribute distName.

        :param str dist_name: distName of checked object
        :param str list_name: name of the checked list
        :return: True if list exists, False otherwise.
        :rtype: bool
        """
        return self.scf_operations.is_in_scf(dist_name, list_name)

    def is_element_in_object(self, dist_name, p_name):
        """ Checks whether given element exists directly under given object.
        The object is mapped by the attribute distName.

        :param str dist_name: distName of checked object
        :param str p_name: name of the checked element
        :return: True if element exists, False otherwise.
        :rtype: bool
        """
        return self.scf_operations.is_in_scf(dist_name, p_name)

    def clone_mo_with_descendant_mos(self, source_mo_dist_name, target_mo_dist_name):
        """ Copies managed object of given source distName and all managed objects that have it in distName
        and creates all these managed objects with source name replaced by target name.

        :param source_mo_dist_name: distName of parent managed object to be cloned
        :param target_mo_dist_name: distName that new managed object and its children
                                    will get in place of source distName
        """
        return self.scf_operations.clone_mo_with_descendant_mos(source_mo_dist_name, target_mo_dist_name)

    def remove_mo_with_descendant_mos(self, dist_name):
        """ Removes managed object with given distName together with all its descendant managed objects.
        I.e. 'SBTS-1900/TNL-4/ETHSVC-1' will be removed together with its descendants:
        'SBTS-1900/TNL-4/ETHSVC-1/ETHIF-1' and 'SBTS-1900/TNL-4/ETHSVC-1/ETHLK-1'.

        :param str dist_name: distName of parent managed object which will be removed
        :except ElementNotFound: raised when parent managed object is not found in loaded SCF
        """
        self.scf_operations.remove_mo_with_descendant_mos(dist_name)

    def get_mo_attribute(self, dist_name, attribute):
        """ Returns value of parameter 'attribute' of managed object indicated in 'dist_name'.
        Example:
        Data: <managedObject distName="SBTS-1900/RAP-1" version="5G17_1707_001">
        Function call: get_mo_attribute("SBTS-1900/RAP-1", "version")
        Return value: "5G17_1707_001"

        :param str dist_name: distName of managed object
        :param str attribute: attribute name of indicated managed object

        :raises KeyError: when managed object named 'dist_name' does not have proper attribute

        :rtype: str
        :return: value of 'attribute'
        """
        return self.scf_operations.get_mo_attribute(dist_name=dist_name,
                                                    attribute=attribute)

    def set_mo_attribute(self, dist_name, attribute, value):
        """ Sets parameter 'attribute' of managed object indicated in 'dist_name' to 'value'.
        Example:
        Data: <managedObject distName="SBTS-1900/RAP-1" version="5G17_1707_001">
        Function call: set_mo_attribute("SBTS-1900/RAP-1", "version", "new_version")
        Updated data: <managedObject distName="SBTS-1900/RAP-1" version="new_version">
        Return value: "new_version"

        :param str dist_name: distName of managed object to be updated
        :param str attribute: attribute to be changed (or set if attribute doesn't exist in
                              indicated managed object)
        :param str value: new value of 'attribute'

        :raises KeyError: when 'attribute' is invalid within the context of raml21.xsd.
                          List of valid attributes: class, version, operation, distName,
                          id, name, vendor, timeStamp
        """
        return self.scf_operations.set_mo_attribute(dist_name=dist_name,
                                                    attribute=attribute,
                                                    value=value)

    def delete_mo_attribute(self, dist_name, attribute):
        """
        Delete ``attribute`` parameter of managed object indicated by ``dist_name``.
        Example:
        Data: <managedObject distName="SBTS-1900/RAP-1" version="5G17_1707_001">
        KW call: Delete MO Attribute    SBTS-1900/RAP-1    version
        Updated data: <managedObject distName="SBTS-1900/RAP-1">

        :param str dist_name: distName of managed object to be updated
        :param str attribute: attribute to be deleted

        :raises KeyError: when 'attribute' is invalid within the context of raml21.xsd.
                          List of valid attributes: class, version, operation, distName,
                          id, name, vendor, timeStamp
        """
        return self.scf_operations.delete_mo_attribute(dist_name=dist_name, attribute=attribute)

    def calculate_delta_scf(self, target_scf_path, actual_scf_path, delta_scf_path, oam_type="COAM"):
        """ Calculates a delta SCF from two full SCFs, that can be used to revert
        the current gNB configuration back to the original one.

        :param target_scf_path: path to the target SCF file with gNB configuration
        :param actual_scf_path: path to the actual SCF file with gNB configuration
        :param delta_scf_path: output path for the delta SCF file. Expect .json format in case of oam_type=COAM
        :param oam_type: string for choosing `COAM` or `MZ`
        """
        delta_scf_calculator = DeltaSCFCalculatorSelector.get_for(oam_type)
        delta_scf_calculator.calculate_delta_scf(target_scf_path, actual_scf_path, delta_scf_path)

    def perform_scf_modification(self, modification_strings):
        """
        Perform SCF modifications.

        There are 3 possible operations: ``add``, ``delete``, and ``modify``. Each
        of them has different possibilities, please refer to the below explanation. Multiple operations can be added at
        the same time via string entries in ``modification_strings`` list.

        Modifications are performed based on provided ManagedObject name(s), for example:

        if ManagedObject has distName="MRBTS-2725/TNLSVC-1/TNL-1/IPNO-1/RTPOL-1", then RTPOL-1 is used;
        if there are more matches for the same mo_name, e.g:
           distName="MRBTS-2725/LNBTS-2725/LNCEL-27251/SIB-0"
           distName="MRBTS-2725/LNBTS-2725/LNCEL-27252/SIB-0",
        then ``mo_name`` will be the last two elements combined together -> mo_name = LNCEL-27251/SIB-0, etc.

        Since a greedy search is performed for provided MO names, multiple matches are possible. For example, if
        MRBTS-2725/WNBTS-1/WNCEL-1 is used in a modification string, objects such as MRBTS-2725/WNBTS-1/WNCEL-11
        or MRBTS-2725/WNBTS-1/WNCEL-13 are considered matches and will be modified as well.
        To avoid that, please put a $ sign at the end of distName: MRBTS-2725/WNBTS-1/WNCEL-1$.

        :param list(str) modification_strings: it consist of modification strings, please refer to the below
                         explanation.


        EXAMPLES FOR ADD OPERATION
        - add parameter to list with condition_key
        (add srcIpPrefixLength parameter with value 27 to routingPolicies <list> element where orderNumber=1):
        'add:RTPOL-1:routingPolicies:srcIpPrefixLength=27|orderNumber=1'

        - add parameter to list element
        (add srcIpAddress parameter with value 0.0.0.0 to <list>; if <list> consists of multilpe <item>s,
        then this operation will affect all of them):
        'add:RTPOL-1:routingPolicies:srcIpAddress=0.0.0.0'

        - add parameter to list
        (add param with value 4, i.e. <p>4</p>, to wncelIdList under WNCELG-1)
        'add:WNCELG-1:wncelIdList::4'

        - add item to list
        (add item with "param_name": "value" entries, e.g., example: add <item> to routingPolicies <list> with entry
        "orderNumber": "5"):
        'add:RTPOL-1:routingPolicies:{"orderNumber": "5"}'

        - add parameter to ManagedObject
        (add shareOfHSDPAUser=100 to WNCELG-1):
        'add:WNCELG-1:shareOfHSDPAUser=100'

        - add list to ManagedObject
        (add cPlaneList <list> element to WNBTS-1)
        'add:WNBTS-1:cPlaneList'

        - add ManagedObject to SCF
        (add second group WNCELG-2 to SCF.
        In square brackets there are 4 groups:
            - class_name
            - dist_name
            - version
            - operation)
        'add:[com.nokia.srbts.wcdma:WNCELG, MRBTS-2725/WNBTS-1/WNCELG-2, WCDMA18_1711_005, create]

        EXAMPLES FOR MODIFY OPERATION
        - modify list parameter with condition_key
        (modify srcIpPrefixLength parameter, i.e., set it to value 24 in routingPolicies <list> element where
        orderNumber=1)
        'modify:RTPOL-1:routingPolicies:srcIpPrefixLength=24|orderNumber=1'

        - modify list parameter
        (modify srcIpAddress parameter, i.e., set it to value 1.1.1.1 in routingPolicies <list>; if <list> consists of
        multilpe <item>s, then this operation will affect all of them)
        'modify:RTPOL-1:routingPolicies:srcIpAddress=1.1.1.1'

        - modify list by creating a new list with provided values
        (modify wncelIdList with new values 1,2,3, or in fact, <p>1</p><p>2</p><p>3</p>)
        'modify:WNCELG-1:wncelIdList=1,2,3'

        - modify list by creating a new list with one value
        (modify wncelIdList with new values 1, or in fact, <p>1</p>)
        'modify:WNCELG-1:wncelIdList=1,'

        - modify param in ManagedObject
        (modify aldScanningInterval under APEQM-1 to value 'enabled')
        'modify:APEQM-1:aldScanningInterval=enabled'


        EXAMPLES FOR DELETE OPERATION
        - delete whole list with condition_key
        (delete staticRoutes <item> under IPRT-1 where destinationIpPrefixLength is 24)
        'delete:IPRT-1:staticRoutes:{}|destinationIpPrefixLength=24'

        - delete a single parameter on list with condition key
        (delete destIpAddr parameter under IPRT-1/staticRoutes where destinationIpPrefixLength is 24)
        'delete:IPRT-1:staticRoutes:destIpAddr|destinationIpPrefixLength=24'

        - delete list parameter which is not located under any <item> element
        (delete test_parameter located in routingPolicies <list> under RTPOL-1 which is not under any <item> element)
        'delete:RTPOL-1:routingPolicies:test_parameter'

        - delete element (list or parameter) in given ManagedObject
        (delete parameter accessBbCapacity under WNCELG-1)
        'delete:WNCELG-1:accessBbCapacity'

        (delete list wncelIdList under WNCELG-1)
        'delete:WNCELG-1:wncelIdList'

        - delete ManagedObject
        (delete whole ManagedObject WNCELG-1)
        'delte:WNCELG-1'
        """

        return self.scf_operations.perform_scf_modification(modification_strings=modification_strings)
